import { randomUUID } from 'crypto';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { isNewerVersion } from '../cli/serverVersion';
import { runNpm } from './npmCommand';
import { selectedOperatingSystemServices } from '../services/OperatingSystemServices';
import { errnoCode } from '../utils/errnoCode';
import { writeFileAtomicSync } from '../utils/writeFileAtomic';
import { getPluginName } from '../hosts/pluginContext';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';

const AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION = 1 as const;
const AUTOMATIC_UPDATE_STATE_FILENAME = 'automatic-cli-update.json';
const NPM_INSTALL_TIMEOUT_MS = 120_000;
const NPM_ROOT_TIMEOUT_MS = 5_000;
const REGISTRY_REQUEST_TIMEOUT_MS = 2_000;
const FAILED_UPDATE_RETRY_INTERVAL_MS = 15 * 60 * 1_000;
const LOCK_INITIALIZATION_GRACE_MS = 1_000;
const LOCK_POLL_INTERVAL_MS = 25;
const LOCK_WAIT_TIMEOUT_MS = 10_000;
const RIVET_PACKAGE_NAME = 'rivet-design';
const RIVET_LATEST_PACKAGE_SPEC = `${RIVET_PACKAGE_NAME}@latest`;
const RIVET_LATEST_REGISTRY_URL =
  'https://registry.npmjs.org/rivet-design/latest';
const SEMVER_PATTERN =
  /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/;
const AUTOMATIC_UPDATE_FAILURE_PHASES = [
  'check',
  'install',
  'refresh',
  'restart',
] as const;
const AUTOMATIC_UPDATE_FAILURE_REASONS = [
  'global_root_unavailable',
  'integration_refresh_failed',
  'invalid_registry_response',
  'npm_install_failed',
  'registry_unavailable',
  'update_in_progress',
  'updated_cli_start_failed',
  'version_verification_failed',
] as const;

export const AUTOMATIC_UPDATE_CHECK_INTERVAL_MS = 60 * 60 * 1_000;

export type AutomaticCliUpdateFailurePhase =
  (typeof AUTOMATIC_UPDATE_FAILURE_PHASES)[number];

export type AutomaticCliUpdateFailureReason =
  (typeof AUTOMATIC_UPDATE_FAILURE_REASONS)[number];

export type AutomaticCliUpdateFailure = {
  currentVersion: string;
  durationMs: number;
  phase: AutomaticCliUpdateFailurePhase;
  reason: AutomaticCliUpdateFailureReason;
  targetVersion?: string;
};

export type AutomaticCliUpdateResult =
  | {
      action: 'continue';
      checkedVersion?: string;
      failure?: AutomaticCliUpdateFailure;
      warning?: string;
    }
  | {
      action: 'blocked';
      failure: AutomaticCliUpdateFailure;
      message: string;
      warning: string;
    }
  | {
      action: 'restart';
      binPath: string;
      durationMs: number;
      installedVersion: string;
      previousVersion: string;
      refreshIntegrations: boolean;
    };

type AutomaticCliUpdateState = {
  checkedAt: number;
  failure?: Pick<
    AutomaticCliUpdateFailure,
    'phase' | 'reason' | 'targetVersion'
  >;
  latestVersion?: string;
  packageRoot: string;
  schemaVersion: typeof AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION;
  status: 'current' | 'failed';
};

export type AutomaticCliUpdateOptions = {
  args: string[];
  binPath: string;
  currentVersion: string;
  env?: NodeJS.ProcessEnv;
  homeDirectory?: string;
  installTimeoutMs?: number;
  lockWaitTimeoutMs?: number;
  now?: () => number;
  packageRoot: string;
};

type RegistryResponse = {
  version: string;
};

type UpdateLock = {
  addOwner: (processId: number) => void;
  release: () => void;
};

export const automaticCliUpdateStatePath = (
  homeDirectory: string = os.homedir(),
): string =>
  path.join(homeDirectory, '.rivet', AUTOMATIC_UPDATE_STATE_FILENAME);

const isRegistryResponse = (value: unknown): value is RegistryResponse => {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const version = (value as { version?: unknown }).version;
  return typeof version === 'string' && SEMVER_PATTERN.test(version);
};

const isFailurePhase = (
  value: unknown,
): value is AutomaticCliUpdateFailurePhase =>
  typeof value === 'string' &&
  AUTOMATIC_UPDATE_FAILURE_PHASES.includes(
    value as AutomaticCliUpdateFailurePhase,
  );

const isFailureReason = (
  value: unknown,
): value is AutomaticCliUpdateFailureReason =>
  typeof value === 'string' &&
  AUTOMATIC_UPDATE_FAILURE_REASONS.includes(
    value as AutomaticCliUpdateFailureReason,
  );

const isAutomaticCliUpdateState = (
  value: unknown,
): value is AutomaticCliUpdateState => {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const state = value as Partial<AutomaticCliUpdateState>;
  if (
    state.schemaVersion !== AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION ||
    typeof state.checkedAt !== 'number' ||
    typeof state.packageRoot !== 'string' ||
    (state.status !== 'current' && state.status !== 'failed')
  ) {
    return false;
  }
  if (
    state.latestVersion !== undefined &&
    (typeof state.latestVersion !== 'string' ||
      !SEMVER_PATTERN.test(state.latestVersion))
  ) {
    return false;
  }
  if (state.failure === undefined) {
    return state.status === 'current';
  }
  return (
    state.status === 'failed' &&
    isFailurePhase(state.failure.phase) &&
    isFailureReason(state.failure.reason) &&
    (state.failure.targetVersion === undefined ||
      (typeof state.failure.targetVersion === 'string' &&
        SEMVER_PATTERN.test(state.failure.targetVersion)))
  );
};

const readUpdateState = (statePath: string): AutomaticCliUpdateState | null => {
  try {
    const parsed: unknown = JSON.parse(fs.readFileSync(statePath, 'utf8'));
    return isAutomaticCliUpdateState(parsed) ? parsed : null;
  } catch {
    return null;
  }
};

const writeUpdateState = (
  statePath: string,
  state: AutomaticCliUpdateState,
): void => {
  fs.mkdirSync(path.dirname(statePath), { recursive: true });
  writeFileAtomicSync(statePath, `${JSON.stringify(state, null, 2)}\n`, {
    mode: 0o600,
  });
};

const persistUpdateState = (
  statePath: string,
  state: AutomaticCliUpdateState,
): void => {
  try {
    writeUpdateState(statePath, state);
  } catch {}
};

const normalizedPath = (filePath: string): string => {
  try {
    return path.normalize(fs.realpathSync(filePath));
  } catch {
    return path.normalize(path.resolve(filePath));
  }
};

const isExcludedExecution = (options: {
  args: string[];
  binPath: string;
  env: NodeJS.ProcessEnv;
  packageRoot: string;
}): boolean => {
  const pathSegments = normalizedPath(options.packageRoot).split(path.sep);
  return (
    options.args[0] === 'mcp' ||
    getPluginName(options.env) !== undefined ||
    options.env.NODE_ENV !== 'production' ||
    options.env.RIVET_AUTO_UPDATE_DISABLED === '1' ||
    options.binPath.split(path.sep).includes('_npx') ||
    pathSegments.includes('_npx') ||
    (pathSegments.includes('.rivet') && pathSegments.includes('channels'))
  );
};

const resolveGlobalPackageRoot = async (
  env: NodeJS.ProcessEnv,
): Promise<{
  packageRoot?: string;
  failure?: AutomaticCliUpdateFailureReason;
}> => {
  const result = await runNpm({
    args: ['root', '-g'],
    env: subprocessEnvironment('packageManager', env),
    timeoutMs: NPM_ROOT_TIMEOUT_MS,
  });
  if (result.error || result.status !== 0 || !result.stdout.trim()) {
    return { failure: 'global_root_unavailable' };
  }
  return {
    packageRoot: path.join(result.stdout.trim(), RIVET_PACKAGE_NAME),
  };
};

const readPackageVersion = (packageRoot: string): string | null => {
  try {
    const parsed: unknown = JSON.parse(
      fs.readFileSync(path.join(packageRoot, 'package.json'), 'utf8'),
    );
    if (
      parsed === null ||
      typeof parsed !== 'object' ||
      Array.isArray(parsed)
    ) {
      return null;
    }
    const version = (parsed as { version?: unknown }).version;
    return typeof version === 'string' && SEMVER_PATTERN.test(version)
      ? version
      : null;
  } catch {
    return null;
  }
};

const checkLatestVersion = async (
  registryUrl: string,
): Promise<
  | { ok: true; version: string }
  | { ok: false; reason: AutomaticCliUpdateFailureReason }
> => {
  try {
    const response = await fetch(registryUrl, {
      headers: { Accept: 'application/json' },
      signal: AbortSignal.timeout(REGISTRY_REQUEST_TIMEOUT_MS),
    });
    if (!response.ok) {
      return { ok: false, reason: 'registry_unavailable' };
    }
    const payload: unknown = await response.json();
    return isRegistryResponse(payload)
      ? { ok: true, version: payload.version }
      : { ok: false, reason: 'invalid_registry_response' };
  } catch {
    return { ok: false, reason: 'registry_unavailable' };
  }
};

export const checkPublishedCliVersion = async (
  env: NodeJS.ProcessEnv = process.env,
): ReturnType<typeof checkLatestVersion> =>
  checkLatestVersion(
    env.RIVET_AUTO_UPDATE_REGISTRY_URL ?? RIVET_LATEST_REGISTRY_URL,
  );

const failureWarning = (failure: AutomaticCliUpdateFailure): string => {
  const recovery = 'Run: npm install -g rivet-design@latest';
  if (failure.targetVersion) {
    return (
      `Rivet could not update to v${failure.targetVersion}; continuing with v${failure.currentVersion}.\n` +
      `${recovery}\n`
    );
  }
  return (
    `Rivet could not check for updates; continuing with v${failure.currentVersion}.\n` +
    `${recovery}\n`
  );
};

const failedResult = (options: {
  currentVersion: string;
  durationMs: number;
  phase: AutomaticCliUpdateFailurePhase;
  reason: AutomaticCliUpdateFailureReason;
  targetVersion?: string;
}): Extract<AutomaticCliUpdateResult, { action: 'continue' }> => {
  const failure: AutomaticCliUpdateFailure = options;
  return { action: 'continue', failure, warning: failureWarning(failure) };
};

const activeUpdateResult = (options: {
  currentVersion: string;
  durationMs: number;
  targetVersion: string;
}): Extract<AutomaticCliUpdateResult, { action: 'blocked' }> => {
  const failure: AutomaticCliUpdateFailure = {
    ...options,
    phase: 'install',
    reason: 'update_in_progress',
  };
  const message = 'Another Rivet process is updating the CLI.';
  return {
    action: 'blocked',
    failure,
    message,
    warning: `${message} The update is still in progress; retry this command in a moment.\n`,
  };
};

const unverifiableInstallResult = (options: {
  currentVersion: string;
  durationMs: number;
  targetVersion: string;
}): Extract<AutomaticCliUpdateResult, { action: 'blocked' }> => {
  const failure: AutomaticCliUpdateFailure = {
    ...options,
    phase: 'install',
    reason: 'version_verification_failed',
  };
  const message = 'The installed Rivet CLI could not be verified.';
  return {
    action: 'blocked',
    failure,
    message,
    warning: `${message} Rivet stopped before loading changed package files. Run: npm install -g rivet-design@latest\n`,
  };
};

const isProcessRunning = (pid: number): boolean => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return errnoCode(error) !== 'ESRCH';
  }
};

const readLockOwners = (lockPath: string): number[] =>
  fs
    .readFileSync(lockPath, 'utf8')
    .split('\n')
    .map((line) => Number.parseInt(line, 10))
    .filter((owner) => !Number.isNaN(owner));

const acquireUpdateLock = (lockPath: string): UpdateLock | null => {
  fs.mkdirSync(path.dirname(lockPath), { recursive: true });
  const tryAcquire = (): boolean => {
    const candidatePath = `${lockPath}.${process.pid}.${randomUUID()}`;
    try {
      fs.writeFileSync(candidatePath, String(process.pid), {
        encoding: 'utf8',
        flag: 'wx',
        mode: 0o600,
      });
      fs.linkSync(candidatePath, lockPath);
      return true;
    } catch (error) {
      if (errnoCode(error) === 'EEXIST') return false;
      throw error;
    } finally {
      fs.rmSync(candidatePath, { force: true });
    }
  };
  let isAcquired = tryAcquire();
  if (!isAcquired) {
    try {
      const owners = readLockOwners(lockPath);
      if (owners.some(isProcessRunning)) return null;
      if (owners.length === 0) {
        const lockAge = Date.now() - fs.statSync(lockPath).mtimeMs;
        if (lockAge < LOCK_INITIALIZATION_GRACE_MS) return null;
      }
      fs.rmSync(lockPath, { force: true });
      isAcquired = tryAcquire();
    } catch {
      return null;
    }
  }
  if (!isAcquired) return null;
  return {
    addOwner: (processId) =>
      fs.appendFileSync(lockPath, `\n${processId}`, 'utf8'),
    release: () => fs.rmSync(lockPath, { force: true }),
  };
};

const waitForUpdateLock = async (
  lockPath: string,
  timeoutMs: number,
): Promise<UpdateLock | null> => {
  const deadline = Date.now() + timeoutMs;
  let lock = acquireUpdateLock(lockPath);
  while (lock === null) {
    const remainingMs = deadline - Date.now();
    if (remainingMs <= 0) return null;
    await new Promise<void>((resolve) => {
      setTimeout(resolve, Math.min(LOCK_POLL_INTERVAL_MS, remainingMs));
    });
    lock = acquireUpdateLock(lockPath);
  }
  return lock;
};

const shouldUseCachedState = (options: {
  currentTime: number;
  isForced: boolean;
  state: AutomaticCliUpdateState | null;
}): boolean => {
  if (options.isForced || !options.state) return false;
  const interval =
    options.state.status === 'failed'
      ? FAILED_UPDATE_RETRY_INTERVAL_MS
      : AUTOMATIC_UPDATE_CHECK_INTERVAL_MS;
  return options.currentTime - options.state.checkedAt < interval;
};

export const checkAndInstallCliUpdate = async (
  options: AutomaticCliUpdateOptions,
): Promise<AutomaticCliUpdateResult> => {
  const startedAt = (options.now ?? Date.now)();
  const now = options.now ?? Date.now;
  const env = options.env ?? process.env;
  if (options.args[0] === 'version' && options.args[1] === 'status') {
    return { action: 'continue' };
  }
  if (
    isExcludedExecution({
      args: options.args,
      binPath: options.binPath,
      env,
      packageRoot: options.packageRoot,
    })
  ) {
    return { action: 'continue' };
  }

  const statePath = automaticCliUpdateStatePath(options.homeDirectory);
  const state = readUpdateState(statePath);
  const isKnownGlobalPackage =
    state !== null &&
    normalizedPath(state.packageRoot) === normalizedPath(options.packageRoot);
  if (!isKnownGlobalPackage) {
    const globalPackage = await resolveGlobalPackageRoot(env);
    if (!globalPackage.packageRoot) {
      return failedResult({
        currentVersion: options.currentVersion,
        durationMs: now() - startedAt,
        phase: 'check',
        reason: globalPackage.failure ?? 'global_root_unavailable',
      });
    }
    if (
      normalizedPath(globalPackage.packageRoot) !==
      normalizedPath(options.packageRoot)
    ) {
      return { action: 'continue' };
    }
  }

  const isForced = options.args[0] === 'update';
  const currentTime = now();
  if (shouldUseCachedState({ currentTime, isForced, state })) {
    if (state?.status === 'failed' && state.failure) {
      return failedResult({
        currentVersion: options.currentVersion,
        durationMs: now() - startedAt,
        ...state.failure,
      });
    }
    if (
      state?.latestVersion &&
      isNewerVersion(state.latestVersion, options.currentVersion) &&
      readPackageVersion(options.packageRoot) === state.latestVersion
    ) {
      return {
        action: 'restart',
        binPath: options.binPath,
        durationMs: now() - startedAt,
        installedVersion: state.latestVersion,
        previousVersion: options.currentVersion,
        refreshIntegrations: true,
      };
    }
    if (
      !state?.latestVersion ||
      !isNewerVersion(state.latestVersion, options.currentVersion)
    ) {
      return { action: 'continue', checkedVersion: state?.latestVersion };
    }
  }

  const latest = await checkPublishedCliVersion(env);
  if (!latest.ok) {
    const failure = failedResult({
      currentVersion: options.currentVersion,
      durationMs: now() - startedAt,
      phase: 'check',
      reason: latest.reason,
    });
    persistUpdateState(statePath, {
      checkedAt: currentTime,
      failure: { phase: 'check', reason: latest.reason },
      packageRoot: options.packageRoot,
      schemaVersion: AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION,
      status: 'failed',
    });
    return failure;
  }

  if (!isNewerVersion(latest.version, options.currentVersion)) {
    persistUpdateState(statePath, {
      checkedAt: currentTime,
      latestVersion: latest.version,
      packageRoot: options.packageRoot,
      schemaVersion: AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION,
      status: 'current',
    });
    return { action: 'continue', checkedVersion: latest.version };
  }

  const lockPath = `${statePath}.lock`;
  const lock = await waitForUpdateLock(
    lockPath,
    options.lockWaitTimeoutMs ?? LOCK_WAIT_TIMEOUT_MS,
  );
  if (lock === null) {
    return activeUpdateResult({
      currentVersion: options.currentVersion,
      durationMs: now() - startedAt,
      targetVersion: latest.version,
    });
  }

  try {
    const packageVersion = readPackageVersion(options.packageRoot);
    if (packageVersion === latest.version) {
      persistUpdateState(statePath, {
        checkedAt: currentTime,
        latestVersion: packageVersion,
        packageRoot: options.packageRoot,
        schemaVersion: AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION,
        status: 'current',
      });
      return {
        action: 'restart',
        binPath: options.binPath,
        durationMs: now() - startedAt,
        installedVersion: packageVersion,
        previousVersion: options.currentVersion,
        refreshIntegrations: true,
      };
    }

    const packageSpec =
      env.RIVET_AUTO_UPDATE_PACKAGE_SPEC ?? RIVET_LATEST_PACKAGE_SPEC;
    const install = await runNpm({
      args: ['install', '-g', packageSpec, '--no-audit', '--no-fund'],
      env: subprocessEnvironment('packageManager', env),
      onStarted: lock.addOwner,
      timeoutMs:
        selectedOperatingSystemServices.operatingSystemFamily === 'windows'
          ? undefined
          : (options.installTimeoutMs ?? NPM_INSTALL_TIMEOUT_MS),
    });
    if (install.error || install.status !== 0) {
      const failure = failedResult({
        currentVersion: options.currentVersion,
        durationMs: now() - startedAt,
        phase: 'install',
        reason: 'npm_install_failed',
        targetVersion: latest.version,
      });
      persistUpdateState(statePath, {
        checkedAt: currentTime,
        failure: {
          phase: 'install',
          reason: 'npm_install_failed',
          targetVersion: latest.version,
        },
        latestVersion: latest.version,
        packageRoot: options.packageRoot,
        schemaVersion: AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION,
        status: 'failed',
      });
      return failure;
    }

    const installedVersion = readPackageVersion(options.packageRoot);
    if (installedVersion === null) {
      return unverifiableInstallResult({
        currentVersion: options.currentVersion,
        durationMs: now() - startedAt,
        targetVersion: latest.version,
      });
    }

    persistUpdateState(statePath, {
      checkedAt: currentTime,
      latestVersion: installedVersion,
      packageRoot: options.packageRoot,
      schemaVersion: AUTOMATIC_UPDATE_STATE_SCHEMA_VERSION,
      status: 'current',
    });
    return {
      action: 'restart',
      binPath: options.binPath,
      durationMs: now() - startedAt,
      installedVersion,
      previousVersion: options.currentVersion,
      refreshIntegrations: true,
    };
  } finally {
    lock.release();
  }
};
